  'we_are_delighted_to_welcome_all_residents_please_reach_out_to_management_for_any_facility_requests': 'എല്ലാ താമസക്കാരെയും സ്വാഗതം ചെയ്യുന്നതിൽ ഞങ്ങൾ സന്തുഷ്ടരാണ്! ഏതെങ്കിലും സൗകര്യ അഭ്യർത്ഥനകൾക്കായി മാനേജ്‌മെന്റുമായി ബന്ധപ്പെടുക.',
  'pool_maintenance_20_july_2026': 'പൂൾ അറ്റകുറ്റപ്പണി – 20 ജൂലൈ 2026',
  'the_swimming_pool_will_remain_closed_on_20th_july_2026_for_annual_chlorination_and_tile_maintenance_we_apologize_for_the_inconvenience': 'വാർഷിക ക്ലോറിനേഷനും ടൈൽ അറ്റകുറ്റപ്പണികൾക്കുമായി 2026 ജൂലൈ 20 ന് നീന്തൽക്കുളം അടച്ചിടും. അസൗകര്യത്തിൽ ഖേദിക്കുന്നു.',
  'independence_day_celebration_15_august_2026': 'സ്വാതന്ത്ര്യദിനാഘോഷം – 15 ഓഗസ്റ്റ് 2026',
  'greenfield_heights_community_cordially_invites_all_residents_to_the_independence_day_celebration_at_the_clubhouse_main_hall_at_8_00_am': 'രാവിലെ 8:00 ന് ക്ലബ്ബ് ഹൗസ് മെയിൻ ഹാളിൽ നടക്കുന്ന സ്വാതന്ത്ര്യദിനാഘോഷത്തിലേക്ക് ഗ്രീൻഫീൽഡ് ഹൈറ്റ്സ് കമ്മ്യൂണിറ്റി എല്ലാ താമസക്കാരെയും സ്നേഹപൂർവ്വം ക്ഷണിക്കുന്നു.',
  'scheduled_power_outage_18_july_2026_block_b': 'ഷെഡ്യൂൾ ചെയ്ത പവർ തടസ്സം – 18 ജൂലൈ 2026 (ബ്ലോക്ക് ബി)',
  'electrical_board_maintenance_scheduled_for_block_b_apartments_on_18_july_between_10_am_2_pm_generator_backup_will_be_available_for_common_areas': 'ബ്ലോക്ക് ബി അപ്പാർട്ടുമെന്റുകൾക്കുള്ള ഇലക്ട്രിക്കൽ ബോർഡ് അറ്റകുറ്റപ്പണി ജൂലൈ 18 ന് രാവിലെ 10 നും ഉച്ചയ്ക്ക് 2 നും ഇടയിൽ ഷെഡ്യൂൾ ചെയ്തിരിക്കുന്നു. പൊതുസ്ഥലങ്ങൾക്ക് ജനറേറ്റർ ബാക്കപ്പ് ലഭ്യമാകും.',
  'monthly_agm_25_july_2026': 'പ്രതിമാസ എ.ജി.എം – 25 ജൂലൈ 2026',
  'annual_general_meeting_for_q2_2026_financial_review_agenda_budget_approval_security_upgrade_proposal_amenity_booking_policy_update': 'ക്യു2 2026 സാമ്പത്തിക അവലോകനത്തിനായുള്ള വാർഷിക പൊതുയോഗം. അജണ്ട: ബജറ്റ് അംഗീകാരം, സുരക്ഷാ നവീകരണ നിർദ്ദേശം, സൗകര്യ ബുക്കിംഗ് നയ അപ്‌ഡേറ്റ്.',
  'lift_inspection_block_c_22_july_2026': 'ലിഫ്റ്റ് പരിശോധന – ബ്ലോക്ക് സി – 22 ജൂലൈ 2026',
  'government_mandated_elevator_inspection_for_block_c_lifts_expected_completion_4_hours_stairways_accessible_at_all_times': 'ബ്ലോക്ക് സി ലിഫ്റ്റുകൾക്കായുള്ള സർക്കാർ നിർബന്ധിത എലിവേറ്റർ പരിശോധന. പ്രതീക്ഷിക്കുന്ന സമയം: 4 മണിക്കൂർ. സ്റ്റെയർവേകൾ എല്ലായ്പ്പോഴും ലഭ്യമാണ്.',
  'new_visitor_parking_policy': 'പുതിയ സന്ദർശക പാർക്കിംഗ് നയം',
  'effective_1_august_2026_visitor_parking_is_limited_to_2_hours_per_visit_between_9_am_and_9_pm_residents_must_pre_register_visitors_via_the_portal': '2026 ഓഗസ്റ്റ് 1 മുതൽ, രാവിലെ 9 നും രാത്രി 9 നും ഇടയിൽ സന്ദർശക പാർക്കിംഗ് ഒരു സന്ദർശനത്തിന് 2 മണിക്കൂറായി പരിമിതപ്പെടുത്തിയിരിക്കുന്നു. താമസക്കാർ പോർട്ടൽ വഴി സന്ദർശകരെ മുൻകൂട്ടി രജിസ്റ്റർ ചെയ്യണം.',
  'fitness_center_new_timings': 'ഫിറ്റ്നസ് സെന്റർ പുതിയ സമയങ്ങൾ',
  'starting_1_august_the_fitness_center_will_be_open_5_am_11_pm_on_weekdays_and_6_am_10_pm_on_weekends_personal_trainers_available_on_sat_sun': 'ഓഗസ്റ്റ് 1 മുതൽ, ഫിറ്റ്‌നസ് സെന്റർ പ്രവൃത്തിദിവസങ്ങളിൽ രാവിലെ 5 മുതൽ രാത്രി 11 വരെയും വാരാന്ത്യങ്ങളിൽ രാവിലെ 6 മുതൽ രാത്രി 10 വരെയും തുറന്നിരിക്കും. ശനി, ഞായർ ദിവസങ്ങളിൽ പേഴ്സണൽ ട്രെയിനർമാർ ലഭ്യമാണ്.',
  'water_conservation_drive_july_2026': 'ജലസംരക്ഷണ ഡ്രൈവ് – ജൂലൈ 2026',
  'we_are_partnering_with_the_local_municipality_for_a_water_conservation_initiative_please_report_leakages_immediately_and_avoid_unnecessary_usage_between_2_pm_5_pm': 'ജലസംരക്ഷണ സംരംഭത്തിനായി ഞങ്ങൾ പ്രാദേശിക മുനിസിപ്പാലിറ്റിയുമായി സഹകരിക്കുന്നു. ദയവായി ചോർച്ചകൾ ഉടനടി റിപ്പോർട്ട് ചെയ്യുക, ഉച്ചയ്ക്ക് 2 നും വൈകുന്നേരം 5 നും ഇടയിലുള്ള അനാവശ്യ ഉപയോഗം ഒഴിവാക്കുക.',
